mapper.select:
select id, member_id as memberId, level_no as levelNo, exp_value as expValue, last_active_time as lastActiveTime, create_time as createTime, update_time as updateTime from member_growth
and member_id = #{memberId}
order by update_time desc, id desc

mapper.update:
update member_growth
set level_no = greatest(level_no, floor((exp_value + #{expValue}) / 100) + 1),
    exp_value = exp_value + #{expValue},
    last_active_time = #{lastActiveTime},
    update_time = #{updateTime}
where member_id = #{memberId}

update member_growth
set exp_value = exp_value - #{exp}, update_time = now()
where member_id = #{memberId} and exp_value >= #{exp}
